-- ----------------------------
-- Table structure for iot_device
-- ----------------------------
DROP TABLE IF EXISTS `iot_device`;
CREATE TABLE `iot_device`  (
  `ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键ID',
  `DEVICE_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备名称',
  `DEVICE_KEY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备标识',
  `DEVICE_SECRET` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备密钥',
  `PRODUCT_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品ID',
  `PROTOCOL_TYPE` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品协议类型（冗余字段，用于优化查询性能）',
  `GATEWAY_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '网关设备ID',
  `DEVICE_STATUS` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'INACTIVE' COMMENT '设备状态',
  `ACTIVE_TIME` datetime NULL DEFAULT NULL COMMENT '激活时间',
  `LAST_ONLINE_TIME` datetime NULL DEFAULT NULL COMMENT '最后在线时间',
  `FIRMWARE_VERSION` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '固件版本',
  `LONGITUDE` decimal(10, 6) NULL DEFAULT NULL COMMENT '经度',
  `LATITUDE` decimal(10, 6) NULL DEFAULT NULL COMMENT '纬度',
  `LOCATION` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '位置描述',
  `TAGS` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签',
  `REMARK` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `SORT_CODE` int NULL DEFAULT NULL COMMENT '排序码',
  `EXT_JSON` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '扩展信息',
  `DELETE_FLAG` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '删除标志',
  `CREATE_TIME` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UK_DEVICE_KEY`(`DEVICE_KEY` ASC) USING BTREE,
  INDEX `IDX_PRODUCT_ID`(`PRODUCT_ID` ASC) USING BTREE,
  INDEX `IDX_GATEWAY_ID`(`GATEWAY_ID` ASC) USING BTREE,
  INDEX `IDX_DEVICE_STATUS`(`DEVICE_STATUS` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物联网设备表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of iot_device
-- ----------------------------

-- ----------------------------
-- Table structure for iot_device_address_config
-- ----------------------------
DROP TABLE IF EXISTS `iot_device_address_config`;
CREATE TABLE `iot_device_address_config`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主键ID',
  `mapping_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '关联映射表ID',
  `protocol_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '协议类型：S7/MODBUS_TCP/OPC_UA/BACNET/FINS/MC',
  `device_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '设备地址（协议特定格式，如：DB1.DBW0、40001、ns=2;s=Temp）',
  `data_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '数据类型：int/float/bool/string/word/dword/real',
  `value_multiplier` decimal(10, 4) NULL DEFAULT 1.0000 COMMENT '数值倍率',
  `value_offset` decimal(10, 4) NULL DEFAULT 0.0000 COMMENT '数值偏移',
  `byte_order` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'BIG_ENDIAN' COMMENT '字节序：BIG_ENDIAN/LITTLE_ENDIAN',
  `register_address` int NULL DEFAULT NULL COMMENT 'Modbus寄存器地址',
  `function_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Modbus功能码：01/02/03/04',
  `slave_address` int NULL DEFAULT NULL COMMENT 'Modbus从站地址',
  `ext_config` json NULL COMMENT '协议特有参数配置',
  `polling_interval` int NULL DEFAULT 0 COMMENT '采集间隔(ms)，0表示使用设备默认',
  `timeout` int NULL DEFAULT 3000 COMMENT '超时时间(ms)',
  `retry_count` int NULL DEFAULT 3 COMMENT '重试次数',
  `enabled` tinyint(1) NULL DEFAULT 1 COMMENT '是否启用',
  `last_success_time` datetime NULL DEFAULT NULL COMMENT '最后成功采集时间',
  `last_error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '最后错误信息',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mapping_protocol`(`mapping_id` ASC, `protocol_type` ASC) USING BTREE,
  INDEX `idx_protocol_type`(`protocol_type` ASC) USING BTREE,
  INDEX `idx_device_address`(`device_address`(100) ASC) USING BTREE,
  INDEX `idx_mapping_id`(`mapping_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '设备地址配置表（协议特定配置）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of iot_device_address_config
-- ----------------------------

-- ----------------------------
-- Table structure for iot_device_data
-- ----------------------------
DROP TABLE IF EXISTS `iot_device_data`;
CREATE TABLE `iot_device_data`  (
  `ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键ID',
  `DEVICE_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备ID',
  `DATA_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '数据类型：PROPERTY-属性，EVENT-事件',
  `DATA_KEY` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '数据标识',
  `DATA_VALUE` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '数据值',
  `DATA_TIME` datetime NOT NULL COMMENT '数据时间',
  `CREATE_TIME` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `IDX_DEVICE_TIME`(`DEVICE_ID` ASC, `DATA_TIME` ASC) USING BTREE,
  INDEX `IDX_DATA_TIME`(`DATA_TIME` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备数据表' ROW_FORMAT = DYNAMIC;

