-- Table structure for iot_device_shadow
-- ----------------------------
DROP TABLE IF EXISTS `iot_device_shadow`;
CREATE TABLE `iot_device_shadow`  (
  `ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键ID',
  `DEVICE_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备ID',
  `REPORTED` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '设备上报数据，JSON格式',
  `DESIRED` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '期望下发数据，JSON格式',
  `VERSION` bigint NULL DEFAULT 0 COMMENT '版本号',
  `UPDATE_TIME` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UK_DEVICE_ID`(`DEVICE_ID` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备影子表' ROW_FORMAT = DYNAMIC;

