-- Records of iot_driver_log
-- ----------------------------

-- ----------------------------
-- Table structure for iot_driver_market
-- ----------------------------
DROP TABLE IF EXISTS `iot_driver_market`;
CREATE TABLE `iot_driver_market`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主键ID',
  `driver_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '驱动类型标识',
  `driver_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '驱动名称',
  `driver_version` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '版本号',
  `source_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'BUILTIN-内置/UPLOADED-上传',
  `install_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'UNINSTALLED/INSTALLED/ENABLED/DISABLED',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '描述',
  `protocol_version` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '协议版本',
  `vendor` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '供应商',
  `icon_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '图标URL',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类',
  `jar_file_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'JAR文件ID',
  `jar_file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'JAR路径',
  `provider_class` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '提供者类名',
  `config_fields` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '配置字段JSON',
  `supports_hot_update` tinyint NULL DEFAULT 0 COMMENT '是否支持热更新',
  `download_count` int NULL DEFAULT 0 COMMENT '安装次数',
  `installed_time` datetime NULL DEFAULT NULL COMMENT '安装时间',
  `enabled_time` datetime NULL DEFAULT NULL COMMENT '启用时间',
  `sort_code` int NULL DEFAULT 100 COMMENT '排序码',
  `ext_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '扩展信息',
  `delete_flag` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '删除标志',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_user` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `update_user` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_driver_type`(`driver_type` ASC) USING BTREE,
  INDEX `idx_source_type`(`source_type` ASC) USING BTREE,
  INDEX `idx_install_status`(`install_status` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '驱动市场表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of iot_driver_market
-- ----------------------------

-- ----------------------------
-- Table structure for iot_gateway_topo
-- ----------------------------
DROP TABLE IF EXISTS `iot_gateway_topo`;
CREATE TABLE `iot_gateway_topo`  (
  `ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键ID',
  `GATEWAY_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '网关设备ID',
  `SUB_DEVICE_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '子设备ID',
  `BIND_TIME` datetime NULL DEFAULT NULL COMMENT '绑定时间',
  `CREATE_TIME` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UK_GATEWAY_SUB`(`GATEWAY_ID` ASC, `SUB_DEVICE_ID` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '网关拓扑关系表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of iot_gateway_topo
-- ----------------------------

-- ----------------------------
-- Table structure for iot_northbound_config
-- ----------------------------
DROP TABLE IF EXISTS `iot_northbound_config`;
CREATE TABLE `iot_northbound_config`  (
  `ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键ID',
  `NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '配置名称',
  `PUSH_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '推送类型：WEBHOOK/MQTT/KAFKA',
  `TARGET_URL` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '目标地址',
  `TARGET_TOPIC` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '目标Topic(MQTT/Kafka使用)',
  `AUTH_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'NONE' COMMENT '认证方式：NONE/BASIC/TOKEN/APIKEY',
  `AUTH_USERNAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '认证用户名',
  `AUTH_PASSWORD` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '认证密码(加密)',
  `AUTH_TOKEN` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '认证Token',
  `CUSTOM_HEADERS` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '自定义HTTP请求头(JSON)',
  `DATA_FILTER` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '数据过滤条件(JSON)',
  `DATA_TRANSFORM` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '数据转换规则(JSON)',
  `ENABLED` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'ENABLE' COMMENT '状态：ENABLE/DISABLE',
  `push_trigger` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '推送触发时机(多选逗号分隔): PROPERTY_REPORT-属性上报,EVENT-事件触发,STATUS_CHANGE-状态变化,MANUAL-手动触发,SCHEDULE-定时推送',
  `schedule_cron` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '定时推送Cron表达式(仅当push_trigger包含SCHEDULE时有效)',
  `schedule_batch_size` int NULL DEFAULT 100 COMMENT '定时推送批量大小',
  `RETRY_TIMES` int NULL DEFAULT 3 COMMENT '重试次数',
  `TIMEOUT` int NULL DEFAULT 5000 COMMENT '超时时间(毫秒)',
  `QOS` int NULL DEFAULT 0 COMMENT 'MQTT QoS等级(0/1/2)',
  `SORT_CODE` int NULL DEFAULT 100 COMMENT '排序码',
  `REMARK` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  `EXT_JSON` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '扩展信息',
  `DELETE_FLAG` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '删除标志',
  `CREATE_TIME` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '北向推送配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of iot_northbound_config
-- ----------------------------

-- ----------------------------
-- Table structure for iot_northbound_device_rel
-- ----------------------------
DROP TABLE IF EXISTS `iot_northbound_device_rel`;
CREATE TABLE `iot_northbound_device_rel`  (
  `ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键ID',
  `CONFIG_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '推送配置ID',
  `DEVICE_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备ID(为NULL表示推送所有设备)',
  `PRODUCT_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品ID(为NULL表示不限产品)',
  `DEVICE_GROUP_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备分组ID',
  `CREATE_TIME` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建用户',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '北向推送设备关联表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of iot_northbound_device_rel
-- ----------------------------

-- ----------------------------
-- Table structure for iot_northbound_log
-- ----------------------------
DROP TABLE IF EXISTS `iot_northbound_log`;
CREATE TABLE `iot_northbound_log`  (
  `ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键ID',
  `CONFIG_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '推送配置ID',
  `CONFIG_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配置名称(冗余)',
  `DEVICE_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '设备ID',
  `DEVICE_KEY` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备标识(冗余)',
  `PUSH_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '推送类型',
  `TARGET_URL` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '目标地址',
  `PAYLOAD` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '推送数据内容',
  `STATUS` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '推送状态：SUCCESS/FAILED/RETRY',
  `RESPONSE_CODE` int NULL DEFAULT NULL COMMENT '响应状态码',
  `RESPONSE_BODY` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '响应内容',
  `ERROR_MESSAGE` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '错误信息',
  `RETRY_COUNT` int NULL DEFAULT 0 COMMENT '重试次数',
  `COST_TIME` int NULL DEFAULT NULL COMMENT '耗时(毫秒)',
  `PUSH_TIME` datetime NOT NULL COMMENT '推送时间',
  `CREATE_TIME` datetime NULL DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '北向推送日志表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of iot_northbound_log
-- ----------------------------

-- ----------------------------
-- Table structure for iot_northbound_statistics
-- ----------------------------
DROP TABLE IF EXISTS `iot_northbound_statistics`;
CREATE TABLE `iot_northbound_statistics`  (
  `ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键ID',
  `CONFIG_ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '推送配置ID',
  `STAT_DATE` date NOT NULL COMMENT '统计日期',
  `TOTAL_COUNT` int NULL DEFAULT 0 COMMENT '总推送次数',
  `SUCCESS_COUNT` int NULL DEFAULT 0 COMMENT '成功次数',
  `FAILED_COUNT` int NULL DEFAULT 0 COMMENT '失败次数',
  `AVG_COST_TIME` int NULL DEFAULT NULL COMMENT '平均耗时(毫秒)',
  `MAX_COST_TIME` int NULL DEFAULT NULL COMMENT '最大耗时(毫秒)',
  `CREATE_TIME` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `UPDATE_TIME` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '北向推送统计表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of iot_northbound_statistics
-- ----------------------------

-- ----------------------------
-- Table structure for iot_product
-- ----------------------------
DROP TABLE IF EXISTS `iot_product`;
CREATE TABLE `iot_product`  (
  `ID` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键ID',
  `PRODUCT_NAME` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品名称',
  `PRODUCT_KEY` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品标识',
  `PRODUCT_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '产品类型：DEVICE-直连设备，GATEWAY-网关设备，SUBSET-子设备',
  `PROTOCOL_TYPE` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '接入协议：MQTT，WEBSOCKET，TCP',
  `DATA_FORMAT` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'JSON' COMMENT '数据格式：JSON，CUSTOM',
  `PRODUCT_DESC` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '产品描述',
  `STATUS` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'ENABLE' COMMENT '状态：ENABLE-启用，DISABLE-禁用',
  `SORT_CODE` int NULL DEFAULT NULL COMMENT '排序码',
  `EXT_JSON` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '扩展信息',
  `DELETE_FLAG` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '删除标志',
  `CREATE_TIME` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `CREATE_USER` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建用户',
  `UPDATE_TIME` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `UPDATE_USER` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改用户',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UK_PRODUCT_KEY`(`PRODUCT_KEY` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '物联网产品表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of iot_product
-- ----------------------------

-- ----------------------------
-- Table structure for iot_product_address_config
-- ----------------------------
DROP TABLE IF EXISTS `iot_product_address_config`;
CREATE TABLE `iot_product_address_config`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主键ID',
  `mapping_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '关联产品属性映射表ID',
  `protocol_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '协议类型：S7/MODBUS_TCP/OPC_UA/BACNET/FINS/MC',
  `device_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '设备地址（协议特定格式，如：DB1.DBW0、40001、ns=2;s=Temp）',
  `data_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '数据类型：int/float/bool/string/word/dword/real',
  `value_multiplier` decimal(10, 4) NULL DEFAULT 1.0000 COMMENT '数值倍率（缩放系数）',
  `value_offset` decimal(10, 4) NULL DEFAULT 0.0000 COMMENT '数值偏移',
  `byte_order` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'BIG_ENDIAN' COMMENT '字节序：BIG_ENDIAN/LITTLE_ENDIAN',
  `ext_config` json NULL COMMENT '协议特有参数配置（JSON格式）',
  `polling_interval` int NULL DEFAULT 0 COMMENT '采集间隔(ms)，0表示使用设备默认',
  `timeout` int NULL DEFAULT 3000 COMMENT '超时时间(ms)',
  `retry_count` int NULL DEFAULT 3 COMMENT '重试次数',
  `enabled` tinyint(1) NULL DEFAULT 1 COMMENT '是否启用',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_mapping_protocol`(`mapping_id` ASC, `protocol_type` ASC) USING BTREE,
  INDEX `idx_protocol_type`(`protocol_type` ASC) USING BTREE,
  INDEX `idx_device_address`(`device_address`(100) ASC) USING BTREE,
  INDEX `idx_mapping_id`(`mapping_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '产品级地址配置表（协议特定配置）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of iot_product_address_config
-- ----------------------------

-- ----------------------------
-- Table structure for iot_product_property_mapping
-- ----------------------------
DROP TABLE IF EXISTS `iot_product_property_mapping`;
CREATE TABLE `iot_product_property_mapping`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '主键ID',
  `product_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '产品ID',
  `thing_model_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '物模型属性ID',
  `identifier` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '属性标识符（冗余字段，便于查询）',
  `enabled` tinyint(1) NULL DEFAULT 1 COMMENT '是否启用',
  `sort_code` int NULL DEFAULT 100 COMMENT '排序',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_product_property`(`product_id` ASC, `identifier` ASC) USING BTREE,
  INDEX `idx_product_id`(`product_id` ASC) USING BTREE,
  INDEX `idx_thing_model_id`(`thing_model_id` ASC) USING BTREE
