INSERT INTO `iot_driver_market` VALUES ('2011965622968877058', 'MQTT', 'MQTT驱动', '3.1.1', 'BUILTIN', 'ENABLED', 'MQTT协议驱动，支持设备通过MQTT协议接入网关', '3.0.0', 'WQS IoT', NULL, 'NETWORK', NULL, NULL, 'vip.xiaonuo.iot.core.driver.spi.provider.MqttDriverProvider', '[{\"key\":\"brokerUrl\",\"label\":\"MQTT Broker地址\",\"type\":\"text\",\"defaultValue\":\"tcp://localhost:1883\",\"placeholder\":\"请输入MQTT Broker地址\",\"tip\":\"MQTT服务器完整地址，如 tcp://localhost:1883\",\"span\":24,\"level\":\"driver\",\"required\":true},{\"key\":\"port\",\"label\":\"MQTT服务端口\",\"type\":\"number\",\"defaultValue\":1883,\"min\":1024,\"max\":65535,\"placeholder\":\"请输入MQTT服务端口\",\"tip\":\"MQTT Broker的监听端口\",\"span\":12,\"level\":\"driver\",\"required\":true},{\"key\":\"topicPrefix\",\"label\":\"Topic前缀\",\"type\":\"text\",\"defaultValue\":\"/device\",\"placeholder\":\"请输入Topic前缀\",\"tip\":\"MQTT消息主题的前缀，默认为 /device\",\"span\":12,\"level\":\"driver\",\"required\":false},{\"key\":\"qos\",\"label\":\"默认QoS级别\",\"type\":\"number\",\"defaultValue\":1,\"min\":0,\"max\":2,\"placeholder\":\"请输入QoS级别\",\"tip\":\"消息质量等级：0-至多一次，1-至少一次，2-仅一次\",\"span\":12,\"level\":\"driver\",\"required\":false}]', 0, 1, '2026-01-16 11:35:02', '2026-01-16 11:35:03', 10, NULL, 'NOT_DELETE', '2026-01-16 08:56:00', '-1', '2026-01-16 12:14:54', '-1');
INSERT INTO `iot_driver_market` VALUES ('2011965623031791617', 'S7', 'S7驱动', '1.0', 'BUILTIN', 'ENABLED', '西门子S7系列PLC驱动，支持S7-200/300/400/1200/1500系列', '3.0.0', 'WQS IoT', NULL, 'INDUSTRIAL', NULL, NULL, 'vip.xiaonuo.iot.core.driver.spi.provider.S7DriverProvider', '[{\"key\":\"defaultPollingInterval\",\"label\":\"默认轮询间隔(ms)\",\"type\":\"number\",\"defaultValue\":5000,\"min\":1000,\"max\":60000,\"placeholder\":\"请输入轮询间隔\",\"tip\":\"数据采集间隔，单位毫秒\",\"span\":24,\"level\":\"driver\",\"required\":false},{\"key\":\"timeout\",\"label\":\"连接超时(ms)\",\"type\":\"number\",\"defaultValue\":5000,\"min\":1000,\"max\":30000,\"placeholder\":\"请输入超时时间\",\"tip\":\"S7连接超时时间，单位毫秒\",\"span\":12,\"level\":\"driver\",\"required\":false},{\"key\":\"host\",\"label\":\"PLC地址\",\"type\":\"text\",\"placeholder\":\"请输入PLC IP地址\",\"tip\":\"西门子PLC的IP地址，如 192.168.1.100\",\"span\":12,\"level\":\"device\",\"required\":true},{\"key\":\"port\",\"label\":\"端口号\",\"type\":\"number\",\"defaultValue\":102,\"min\":1,\"max\":65535,\"placeholder\":\"请输入端口号\",\"tip\":\"S7协议端口，默认102\",\"span\":12,\"level\":\"device\",\"required\":false},{\"key\":\"rack\",\"label\":\"机架号\",\"type\":\"number\",\"defaultValue\":0,\"min\":0,\"max\":7,\"placeholder\":\"请输入机架号\",\"tip\":\"PLC机架号，S7-200/1200通常为0\",\"span\":12,\"level\":\"device\",\"required\":false},{\"key\":\"slot\",\"label\":\"插槽号\",\"type\":\"number\",\"defaultValue\":2,\"min\":0,\"max\":31,\"placeholder\":\"请输入插槽号\",\"tip\":\"CPU插槽号，S7-200/1200通常为2\",\"span\":12,\"level\":\"device\",\"required\":false},{\"key\":\"interval\",\"label\":\"采集间隔(ms)\",\"type\":\"number\",\"defaultValue\":5000,\"min\":1000,\"max\":60000,\"placeholder\":\"请输入采集间隔\",\"tip\":\"此设备的数据采集间隔，单位毫秒\",\"span\":12,\"level\":\"device\",\"required\":false}]', 0, 1, '2026-01-16 12:17:24', '2026-01-16 12:17:33', 10, NULL, 'NOT_DELETE', '2026-01-16 08:56:00', '-1', '2026-01-16 12:17:33', '1543837863788879871');
INSERT INTO `iot_driver_market` VALUES ('2011965623098900481', 'MODBUS_TCP', 'Modbus TCP驱动', '1.0', 'BUILTIN', 'ENABLED', '支持Modbus TCP协议的工业设备驱动，适用于PLC、传感器、仪表等设备', '3.0.0', 'WQS IoT', NULL, 'INDUSTRIAL', NULL, NULL, 'vip.xiaonuo.iot.core.driver.spi.provider.ModbusTcpDriverProvider', '[{\"key\":\"pollingInterval\",\"label\":\"默认轮询间隔\",\"type\":\"number\",\"defaultValue\":5,\"min\":1,\"max\":60,\"placeholder\":\"请输入默认轮询间隔\",\"tip\":\"设备轮询频率的默认值（秒）\",\"span\":12,\"level\":\"driver\",\"required\":false},{\"key\":\"timeout\",\"label\":\"默认超时时间\",\"type\":\"number\",\"defaultValue\":3,\"min\":1,\"max\":10,\"placeholder\":\"请输入默认超时时间\",\"tip\":\"单次请求的超时时间（秒）\",\"span\":12,\"level\":\"driver\",\"required\":false},{\"key\":\"host\",\"label\":\"IP地址\",\"type\":\"text\",\"defaultValue\":\"\",\"placeholder\":\"请输入设备IP地址\",\"tip\":\"设备的IP地址\",\"span\":12,\"level\":\"device\",\"required\":true},{\"key\":\"port\",\"label\":\"端口\",\"type\":\"number\",\"defaultValue\":502,\"min\":1,\"max\":65535,\"placeholder\":\"请输入端口\",\"tip\":\"Modbus TCP端口\",\"span\":12,\"level\":\"device\",\"required\":true},{\"key\":\"slaveAddress\",\"label\":\"从站地址\",\"type\":\"number\",\"defaultValue\":1,\"min\":1,\"max\":247,\"placeholder\":\"请输入从站地址\",\"tip\":\"Modbus从站地址(1-247)\",\"span\":12,\"level\":\"device\",\"required\":true},{\"key\":\"pollingInterval\",\"label\":\"轮询间隔\",\"type\":\"number\",\"min\":1,\"max\":60,\"placeholder\":\"留空使用驱动默认值\",\"tip\":\"覆盖驱动默认的轮询间隔（秒）\",\"span\":12,\"level\":\"device\",\"required\":false},{\"key\":\"timeout\",\"label\":\"超时时间\",\"type\":\"number\",\"min\":1,\"max\":10,\"placeholder\":\"留空使用驱动默认值\",\"tip\":\"覆盖驱动默认的超时时间（秒）\",\"span\":12,\"level\":\"device\",\"required\":false}]', 0, 1, '2026-01-16 12:17:27', '2026-01-16 12:17:29', 10, NULL, 'NOT_DELETE', '2026-01-16 08:56:00', '-1', '2026-01-16 12:17:29', '1543837863788879871');
INSERT INTO `iot_driver_market` VALUES ('2011965623166009346', 'HTTP', 'HTTP驱动', '1.1', 'BUILTIN', 'ENABLED', 'HTTP协议驱动，支持RESTful API设备接入', '3.0.0', 'WQS IoT', NULL, 'NETWORK', NULL, NULL, 'vip.xiaonuo.iot.core.driver.spi.provider.HttpDriverProvider', '[{\"key\":\"baseUrl\",\"label\":\"基础URL\",\"type\":\"text\",\"placeholder\":\"请输入基础URL\",\"tip\":\"如: http://192.168.1.100:8080\",\"span\":24,\"level\":\"driver\",\"required\":true},{\"key\":\"authType\",\"label\":\"认证方式\",\"type\":\"select\",\"options\":[{\"value\":\"\",\"label\":\"无需认证\"},{\"value\":\"Bearer\",\"label\":\"Bearer Token\"},{\"value\":\"Basic\",\"label\":\"Basic Auth\"}],\"placeholder\":\"请选择认证方式\",\"tip\":\"默认无需认证\",\"span\":12,\"level\":\"driver\",\"required\":false},{\"key\":\"authToken\",\"label\":\"认证Token\",\"type\":\"password\",\"placeholder\":\"请输入认证Token\",\"tip\":\"如需认证时填写\",\"span\":12,\"level\":\"driver\",\"required\":false},{\"key\":\"timeout\",\"label\":\"超时时间(毫秒)\",\"type\":\"number\",\"defaultValue\":10000,\"min\":1000,\"max\":60000,\"placeholder\":\"请输入超时时间\",\"tip\":\"HTTP请求超时时间\",\"span\":12,\"level\":\"driver\",\"required\":false}]', 0, 1, '2026-01-16 12:17:28', '2026-01-16 12:17:34', 10, NULL, 'NOT_DELETE', '2026-01-16 08:56:00', '-1', '2026-01-16 12:17:34', '1543837863788879871');
